import React from "react";
const Header = () => {
  return (
    <header className="flex justify-start items-start">
      <img src="/images/icon.png" alt="Icon" className="h-12 w-auto" />
      <h1 className="ml-4">My Website</h1>
    </header>
  );
};

export default Header;
